def calc(z):
 ics=[]; ns=[]
 for dt,g in z.groupby(z.index):
  if len(g)>=8 and g.f.nunique()>1 and g.y.nunique()>1: ics.append(g.f.corr(g.y,method='spearman')); ns.append(len(g))
