import pandas as pd,numpy as np
from scipy.stats import spearmanr
A=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
d={a:pd.read_csv('../persistent/stock_data/'+a+'.csv',parse_dates=['date']).sort_values('date').set_index('date') for a in A}
r=pd.DataFrame({a:d[a].close.pct_change() for a in A})
# downside asymmetry: recent negative-return magnitude relative to positive magnitude; low values favor assets with healthier upside
neg=r.clip(upper=0).abs().rolling(15,min_periods=10).mean(); pos=r.clip(lower=0).rolling(15,min_periods=10).mean()
raw=(pos-neg)/(pos+neg+1e-12)
rows=[]; sig=[]
for dt in sorted(set().union(*[set(x.index) for x in d.values()])):
 vals=raw.loc[dt] if dt in raw.index else pd.Series(index=A,dtype=float)
 for a in A:sig.append((dt,a,vals.get(a,np.nan)))
 f=[];y=[]
 for a in A:
  if dt not in d[a].index or not np.isfinite(vals.get(a,np.nan)):continue
  i=d[a].index.get_loc(dt)
  if i+1<len(d[a]):f.append(vals[a]);y.append(d[a].close.iloc[i+1]/d[a].close.iloc[i]-1)
 if len(f)>=8:rows.append((dt,spearmanr(f,y).statistic,len(f)))
x=pd.DataFrame(rows,columns=['date','ic','n']);print('dates',len(x),'avg_n',x.n.mean(),'IC',x.ic.mean(),'ICIR',x.ic.mean()/x.ic.std(),'hit',(x.ic>0).mean())
for lo,hi in [('2020','2022'),('2023','2024'),('2025','2026'),('2026-07','2027')]:
 q=x.set_index('date').loc[lo:hi].ic;print(lo,len(q),q.mean(),q.mean()/q.std())
o=pd.DataFrame(sig,columns=['date','asset','signal']);o.to_csv('../persistent/factor_signals_miner_3_20270225_downside_asymmetry.csv',index=False);print('turn',o.pivot(index='date',columns='asset',values='signal').rank(axis=1,pct=True).diff().abs().mean(axis=1).mean())

